 if matched!=10 or conflicts!=[('603517','2026-07-03','price_basis_conflict'),('603517','2026-07-31','price_basis_conflict')]:raise ValueError('twentyfourth quote conflict scope changed')
 audit.update(source_refs=[{k:v for k,v in s.items()if k!='text'}for s in sources],stock_reviews=reviews,stock_endpoint_points=matched,stock_return_windows=6,review_note='12股票端点10匹配，绝味两端点复权冲突保留；仅三家6收益跨源一致。',boundary='沿用1e-9阈值；绝味主源同窗收益仅作主源描述，不认证跨源一致。既有其他冲突不关闭。')
